import { execFileSync } from "node:child_process";
import * as fs from "node:fs";
import * as path from "node:path";

/**
 * The Material Symbols subset is generated by scripts/build/material-symbols-subset.py,
 * which only sees an icon name if the code references it in one of the shapes it
 * knows how to collect. When a name is reachable at runtime but not collected,
 * the browser cannot resolve the ligature and renders its own source text —
 * "TRENDING_FLAT" appeared as literal text on the bursar dashboard's Collected
 * card because StatCard builds the name in a ternary assigned to a local.
 *
 * This asserts the icons the app can actually render resolve in the shipped
 * font, so that class of bug fails loudly instead of shipping.
 */

const ROOT = path.join(__dirname, "..", "..");
const FONT = path.join(ROOT, "public/fonts/material-symbols-outlined.woff2");
const SCRIPT = path.join(ROOT, "scripts/build/material-symbols-subset.py");

// Icons reachable only through runtime construction, plus the ones a broken
// collector takes with them. trending_up resolved fine; the other two did not.
const RUNTIME_CONSTRUCTED = ["trending_up", "trending_down", "trending_flat"];

function readLigatures(): Set<string> | null {
  if (!fs.existsSync(FONT) || !fs.existsSync(SCRIPT)) return null;
  const probe = [
    "import importlib.util, sys",
    "from fontTools.ttLib import TTFont",
    `spec = importlib.util.spec_from_file_location('ms', ${JSON.stringify(SCRIPT)})`,
    "m = importlib.util.module_from_spec(spec)",
    "try:",
    "    spec.loader.exec_module(m)",
    "except SystemExit:",
    "    pass",
    `have = m.collect_ligature_map(TTFont(${JSON.stringify(FONT)}))`,
    "print('\\n'.join(sorted(have)))",
  ].join("\n");
  try {
    const out = execFileSync("python3", ["-c", probe], { encoding: "utf8", timeout: 120_000 });
    return new Set(
      out
        .split("\n")
        .map((s) => s.trim())
        .filter(Boolean),
    );
  } catch {
    // python3 or fontTools unavailable (CI images often lack fontTools).
    return null;
  }
}

describe("material symbols subset", () => {
  const ligatures = readLigatures();
  // fontTools is a build-time python dependency; if the environment cannot read
  // the font, fall back to skipping the font assertions rather than failing.
  const itFont = ligatures ? it : it.skip;

  itFont("resolves every runtime-constructed icon in the shipped font", () => {
    const missing = RUNTIME_CONSTRUCTED.filter((n) => !ligatures!.has(n));
    expect(missing).toEqual([]);
  });

  it("collects runtime-constructed icons at build time", () => {
    // Guards the root cause rather than the symptom: the collector must handle
    // `const x = cond ? "a" : "b"` so the ligature reaches the subset.
    const script = fs.readFileSync(SCRIPT, "utf8");
    expect(script).toContain("ternary_assign");
    expect(script).toMatch(/dynamic\s*\|=\s*_quoted_words/);
  });

  itFont("ships a non-trivial ligature set", () => {
    expect(ligatures!.size).toBeGreaterThan(250);
  });
});
